const APP_VERSION='2026.10.16-02';
const eras=[
{id:'1G',year:'20世纪80年代',title:'失联的呼叫',theme:'探索与发现',keys:'模拟通信 · 移动电话 · 无线覆盖',color:'#ffc36c',open:'模拟测试记录显示，一次早期移动电话呼叫没有接通；原因尚未查明。',intro:['这条记录只说明呼叫失败，尚不能判断问题出在终端、无线链路还是网络节点。','先沿着终端、无线信号和基站逐项检查，再根据证据判断原因。'],question:'电话无法接通，你决定先检查什么？',opts:[['检查移动电话','设备能够正常启动，也能发起呼叫。暂时没有发现明显故障。','至少电话还愿意工作。我们再看看外部条件。'],['检查无线信号','本次模拟中，开阔且遮挡较少的位置信号较稳定；进入建筑遮挡较多、覆盖条件较弱的区域后，信号明显减弱。','这个发现很关键。也许问题不在电话，而在它能够连接到网络的范围。'],['检查基站设施','基站与相关网络设备运行正常，没有发现明显异常。','设施没有明显问题。下一步，我们可以比较不同位置的通话表现。']],truth:'测试人员把电话移到信号条件较稳定的位置，再次拨号。这一次电话成功接通。真正的问题是无线信号覆盖不足。电话没有坏，网络设施也没有明显异常，只是刚才的位置超出了稳定通信范围。早期移动通信需要不断扩大覆盖，才能让人们走得更远、通话更稳定。',reveal:'测试记录显示，呼叫失败与无线覆盖不足有关。终端和基站设施未见明显异常，稳定通信范围仍是早期移动网络需要持续解决的问题。',moment:'一位普通用户在城市边缘尝试用移动电话联系家人。第一次呼叫失败后，他走回信号较好的区域，终于听到了家人的声音。移动电话让人们不再完全依赖固定电话线路，但早期移动通信仍受到覆盖范围和通话能力的限制。',achievement:'发现并解决无线信号覆盖不足导致的呼叫失败。',record:'移动电话带来自由移动通话的可能，也暴露了早期覆盖的局限。',core:'通信开始摆脱固定线路，但移动通话仍受到网络覆盖条件的限制。',end:'调查表明，早期移动通话受覆盖范围限制。人们很快也希望传递不必实时接听的信息，移动通信由此继续扩展。',object:'早期移动电话',objectInfo:'早期移动电话通过无线电与蜂窝网络连接，让用户摆脱固定线路进行移动通话。覆盖范围和通话能力是早期网络的重要限制。'},
{id:'2G',year:'20世纪90年代',title:'迟迟未抵达的短信',theme:'传情与选择',keys:'数字通信 · GSM · 短信',color:'#82d9ff',open:'情境记录显示：一条短信已从终端提交，却迟迟没有送达；原因尚未查明。',intro:['先区分手机端的提交状态与接收端的送达状态；两者之间还隔着网络服务流程。','1G让人们能够移动通话，但语音交流仍需要实时接通。沿着短信经过的环节逐步检查，找出信息停留在哪里。'],question:'一位年轻人刚抵达陌生城市，想向家人报平安，但家人暂时无法接听电话。你会怎么做？',opts:[['继续拨打电话','电话仍然没有接通。你意识到，实时通话要求双方在合适的时间建立连接。','实时通话需要双方同时在线，有没有更灵活的办法？'],['发送短信','短信成功提交，但接收端迟迟没有收到。','看来，文字也有自己的旅程。我们得查查它卡在了哪里。'],['等待对方主动联系','你避免了重复拨号，却仍然没有及时传递消息。','等待有时有用，但通信技术的意义，正是帮助人们更主动地跨越距离。']],secondary:{title:'互动调查：短信为什么没有抵达？',opts:[['检查发送终端','短信内容和发送操作正常，终端已成功提交短信。','终端已经把短信交出去了。'],['检查无线连接','手机信号稳定，设备正常接入网络。','无线连接正常，我们沿着短信的旅程继续查。'],['检查短信服务中心','记录显示短信已经进入服务中心，却没有被正确转发。','线索指向服务中心的转发配置。']]},truth:'你和澜修正测试环境中的短信转发配置，重新提交短信。几秒后，接收端显示：“我已经平安到达，不用担心。”电话传递实时声音，而短信让信息可以先出发，再等待对方阅读。',reveal:'测试短信成功送达。与实时通话不同，短信可以先提交，再由网络转发，等待接收者阅读；服务中心的转发配置也需要保持可靠。',moment:'年轻人看到家人的回复，终于放下心来。数字移动通信不仅支持语音通话，也让短信成为重要的信息交流方式，人们拥有了更灵活的沟通选择。',achievement:'通过排查终端、无线连接和短信服务中心，解决转发异常。',record:'短信让重要消息能够跨越时间传递。',core:'移动通信从以语音为主，进一步扩展到数字信息传递。',end:'数字移动通信扩展了语音之外的信息传递。随着网页、图片和多媒体服务进入手机，移动网络还要承载更多数据。',object:'数字移动电话',objectInfo:'2G网络采用数字通信，除语音外也支持短信等数字服务。短信通过网络服务中心转发，不要求发送者和接收者同时通话。'},
{id:'3G',year:'21世纪初',title:'消失的画面',theme:'解谜与发现',keys:'移动互联网 · 网页浏览 · 多媒体',color:'#8aabff',open:'模拟测试现场里，网页文字已经显示，图片却迟迟没有完整加载。',intro:['文字先显示、图片未完整加载，问题可能出在传输、终端处理或内容服务的不同环节。','从网络传输、终端兼容性和源文件完整性入手，逐项核对这些线索。'],question:'寻找消失的画面。你先调查哪个环节？',opts:[['检查网络传输','测试发现，较大的图片文件需要更长时间才能传输完成。','有些内容并没有消失，只是传得太慢了。'],['检查手机浏览器','部分图片格式无法被当前浏览器正确处理。','数据到了，不代表设备就一定能正确显示。'],['检查网页文件','服务器上的部分测试图片文件不完整，与原始文件存在差异。','这次的问题，可能不止一个原因。']],truth:'网络测试表明，大文件传输速度不足；浏览器无法正确处理部分图片格式；服务器上还有不完整的测试文件。你们调整测试条件、使用兼容格式，并重新发布完整文件。网页再次加载，图片完整显示。没有一个万能按钮能解决所有问题：数据要传得来，设备要看得懂，内容本身也必须正确。',reveal:'测试结果显示，网页显示依赖多个环节协同：数据需要传输完整，终端需要兼容内容，服务端也要提供有效文件。',moment:'一名学生用手机查阅学习资料，终于看到了完整的文章和图片。移动互联网让人们通过手机获取信息、浏览网页，并探索更多数字服务。手机不再只是通信工具，也成为连接信息世界的重要入口。',achievement:'通过排查传输、兼容性和文件完整性问题，恢复网页显示。',record:'手机开始成为获取互联网信息的重要工具。',core:'移动互联网体验需要网络、终端和互联网服务协同工作。',end:'移动网页打开了信息入口，但多媒体和实时服务会进一步考验网络承载、终端处理与服务响应。',object:'移动网页窗口',objectInfo:'GPRS等早期移动数据服务已支持手机上网。3G进一步提高数据承载能力，推动网页和多媒体应用；完整体验还依赖网络、终端兼容性与服务器内容。'},
{id:'4G',year:'2010年代',title:'卡住的直播',theme:'速度与决策',keys:'LTE · 高速移动网络 · 视频直播',color:'#b29aff',open:'模拟测试现场的一段体育直播突然停住，缓冲图标不断旋转。',intro:['播放中断可能与画质设置、网络状况或视频服务有关，先观察缓冲状态再判断。','可以从画质、网络状况或视频服务开始排查。'],question:'先采取什么措施？',opts:[['降低视频画质','视频所需的数据量减少，播放有所改善，但仍然偶尔卡顿。','画质降低缓解了一部分压力，但我们还要继续排查。'],['检查网络状况','测试区域同时使用网络的用户较多，部分网络资源较为紧张。','网络拥塞会影响数据能否持续及时到达。'],['检查视频服务','部分视频请求响应时间较长，服务端记录存在异常。','服务响应也可能成为整条链路的瓶颈。']],truth:'问题由多个环节共同造成：网络拥塞使视频数据不能持续到达；手机解码高分辨率视频时负担较重；部分视频服务请求响应缓慢。你们调整测试网络条件、选择适合设备的画质，并修正服务配置。直播重新播放，画面流畅，声音与画面同步。',reveal:'直播恢复后，端到端体验的关键也更清楚了：网络、终端和服务需要协同工作，单一测速数值不能代表所有使用感受。',moment:'体育迷终于看到了比赛的关键进球。另一位用户则通过手机完成了移动支付。高速移动网络推动视频、直播、线上娱乐和移动服务发展，数字生活变得更加丰富。',achievement:'排查网络拥塞、设备解码和视频服务响应异常。',record:'流畅视频与移动服务成为日常数字生活的重要组成部分。',core:'更好的用户体验不仅依赖网络速度，也需要终端和服务协同。',end:'视频与移动服务成为日常应用后，更多设备也需要稳定协同。下一阶段的通信研究将面对更复杂的连接与系统要求。',object:'智能手机直播界面',objectInfo:'LTE及其演进推动移动宽带、视频与移动服务；LTE-Advanced获IMT-Advanced认可。馆藏Atrix 4G为HSPA+终端，不是LTE设备。端到端体验仍受网络、设备和服务影响。'},
{id:'5G',year:'当代及持续演进',title:'失去响应的智能工厂',theme:'协作与系统决策',keys:'5G · 低时延 · 大规模连接 · 工业互联网',color:'#75e7c1',open:'模拟工厂协同测试中，一台机械臂没有按时响应控制指令；故障来源尚待调查。',intro:['响应超时尚不能区分网络、传感器或控制程序的问题，需要逐项核对。','调查需要覆盖网络、传感器和控制程序；它们共同影响协同结果。'],question:'决定排查顺序。',opts:[['优先检查5G网络','网络记录显示，部分数据传输出现延迟，测试网络的资源分配需要调整。','网络是信息通路，我们先记录这个线索。'],['优先检查机械臂','传感器的部分位置反馈数据不稳定，可能影响设备状态判断。','设备状态反馈同样关键。'],['优先检查控制系统','任务记录中出现等待队列，部分控制指令没有按预期顺序处理。','控制系统要协调任务，等待队列值得关注。']],truth:'逐步协作排查：第一步调整网络配置，部分数据传输恢复正常，但机械臂仍偶尔停止；第二步校准传感器，设备反馈稳定，但仍有任务未及时执行；第三步检查控制系统，发现异常期间部分任务进入等待队列。在本次模拟中清理异常任务并修正调度配置后，测试响应改善；这不是现实工业系统的安全认证。网络传递信息，传感器反馈状态，控制系统协调任务。',reveal:'模拟测试显示，网络、传感器与控制程序共同影响设备协作。5G拓展了连接能力，但可靠应用仍取决于完整系统、部署条件与安全机制。',moment:'工程师在控制中心观察设备状态，自动化生产线持续运行。设备联网与工业通信早已存在；5G进一步拓展工业生产、联网设备和数字化服务中的连接能力。应用仍需考虑网络条件、设备安全、系统可靠性与异常保护。',achievement:'通过排查网络、传感器和控制系统，解决设备协同异常。',record:'感受通信技术在智能生产和数字化应用中的作用。',core:'5G为多设备协同和工业互联网提供了重要的通信基础。',end:'移动通话、数字信息、移动互联网与设备连接逐步扩展了通信边界。下一步可以继续追问：通信、环境感知与数字系统如何协同？这仍是研究问题。',object:'工厂机械臂与传感器',objectInfo:'5G为工业互联网、设备连接和协同提供通信基础。实际应用仍依赖传感器、控制程序、安全机制及异常保护共同工作。'},
{id:'6G',year:'研究与发展阶段',title:'消失的数字世界',theme:'推理与未来抉择',keys:'6G研究 · 通信感知融合 · AI · 数字孪生',color:'#e2c479',open:'本项目虚构的未来研究模拟中，测试车已驶过路口，数字模型里的车辆却仍停在原地；另一栋建筑的模型状态也与现场设定不符。',intro:['这次的问题不只在于信息能否传到，还要核对感知结果、分析判断与数字模型是否准确。','先比较模拟数据、到达时间、模型输出与场景参考状态，再判断问题出现在哪个环节。'],question:'选择调查方向。',opts:[['检查通信数据','车辆状态数据已经生成，但部分数据的到达时间明显晚于预期。','数据没有消失，只是迟到了。我们先查查它在传输过程中发生了什么。'],['检查环境感知','模拟传感器记录与场景参考状态存在差异，需要进一步确认感知结果是否准确。','系统收到什么信息很重要，但系统看到的世界是否正确，同样重要。'],['检查人工智能分析','部分数据已经进入平台，但模型输出的状态判断与实际情况不一致。','数据到了，不代表结论就一定正确。我们得看看系统怎样理解这些信息。']],truth:'调查方向A：数据源正常生成原始位置数据；追踪发现多个设备集中上传时部分传输耗时增加，调度不及时；对比生成、到达和模型更新时间发现过期任务延迟了新状态更新。调整本次模拟的传输调度和更新流程后，模型位置更新滞后有所改善，不代表现实系统完全同步。方向B：将模拟传感器记录与参考状态对照，核查传感器校准与数据质量，再重复验证。方向C：对比原始数据与模型输出，修正不合适的分析配置，验证结果改善。通信、感知或分析任一环节都可能让数字世界与现实不一致。本章是研究方向构建的未来情境，6G仍处研究发展阶段。',reveal:'调查发现，测试情境中的数据传输与模型更新存在滞后；感知误差或分析偏差也可能造成现实与数字模型不一致。模型输出仍需原始数据和现场状态验证。',moment:'项目模拟城市的参考状态与数字模型并列显示，用于观察更新滞后和误差；不是现实6G城市的运行记录。面向未来的通信研究中，通信、感知、人工智能与数字孪生等技术有望进一步结合，为智能交通、城市管理和沉浸式交互提供新可能。相关能力仍在研究发展，数据质量、实时性、系统安全和智能分析可靠性仍是问题。',achievement:'通过调查通信、感知或智能分析环节，定位数字世界与现实不一致的原因。',record:'理解未来通信如何可能帮助数字世界更及时地反映现实变化。',core:'未来通信探索不只是追求更高速度，也涉及通信、感知、人工智能与数字系统协同。6G仍处于研究发展阶段。',end:'从最初让人们能够移动通话，到让信息走进手机，再到让设备连接起来，我们看到通信边界不断拓展。未来还要探索如何让通信、感知和智能系统更好协同。技术可以不断进步，但真正重要的，始终是它能够为人类解决什么问题。',object:'数字孪生城市界面',objectInfo:'AI、传感器和数字孪生已有应用，并非6G发明。IMT-2030提出通信感知融合、AI与通信融合等愿景，其系统集成仍需研究验证。本项目的城市及故障是虚构模拟，不是商用6G实测。'}
];
eras.find(item=>item.id==='2G').secondary.opts.push(['检查用户号码配置','接收号码格式和用户配置正常，没有发现异常。','号码配置线索正常，可与短信服务中心的转发记录相互印证。']);
eras.find(item=>item.id==='4G').secondary={title:'深入调查：直播为何卡顿？',opts:[['检查网络容量','用户和数据流量增长会增加网络资源压力。','先判断流量需求是否超过了可用资源。'],['检查基站负载','热点区域的并发用户较多，资源调度需要核对。','集中使用会让局部负载成为瓶颈。'],['检查数据路径','追踪无线接入到视频服务之间的数据传输环节。','端到端路径中的排队也会带来缓冲。'],['检查视频服务','部分请求响应偏慢，核对服务配置与内容适配。','网络之外，服务响应同样影响播放。']]};
eras.find(item=>item.id==='3G').opts.push(['检查网页服务响应','部分网页请求响应较慢，测试内容需要核对完整性。','服务端也是体验链路的一环；把这条线索与网络和终端记录一起分析。']);
eras.find(item=>item.id==='3G').opts.push(['检查手机网络连接','测试手机已经接入移动网络，但稳定连接并不等于网页数据已及时抵达。','网络已接通是重要线索；接下来还要检查传输速度与终端、服务表现。']);
