function homeFormalProgressStatus(saved=homeFormalState()){
  if(!saved||typeof saved!=='object'||Array.isArray(saved))return {hasProgress:false,reasons:[]};
  const eraIds=new Set(eras.map(era=>era.id)),validNodes=new Set(['entry','scene','investigation','technology','archive']),reasons=[];
  const add=(reason)=>{if(!reasons.includes(reason))reasons.push(reason)};
  const hasEra=(items)=>Array.isArray(items)&&items.some(id=>eraIds.has(id));
  for(const field of ['visited','completed','order'])if(hasEra(saved[field]))add(field);
  if(saved.explorationStarted===true)add('explorationStarted');
  if(saved.reviewGuideActive===true)add('reviewGuideActive');
  if(Number.isSafeInteger(saved.reviewGuideStage)&&saved.reviewGuideStage>0&&saved.reviewGuideStage<=6)add('reviewGuideStage');
  if(saved.clues&&typeof saved.clues==='object'&&Object.entries(saved.clues).some(([era,items])=>eraIds.has(era)&&Array.isArray(items)&&items.length>0))add('clues');
  const hasEraRecord=(items,allowStringId=false)=>Array.isArray(items)&&items.some(item=>{
    if(item&&typeof item==='object')return eraIds.has(item.era)||eraIds.has(item.eraId);
    if(!allowStringId||typeof item!=='string')return false;
    const match=item.match(/(?:^|[._-])([1-6])g(?:[._-]|$)/i);
    return !!match&&eraIds.has(`${match[1]}G`);
  });
  if(hasEraRecord(saved.logs))add('logs');
  if(hasEraRecord(saved.evidence,true))add('evidence');
  const tasks=saved.tasks&&typeof saved.tasks==='object'&&!Array.isArray(saved.tasks)?saved.tasks:{};
  const taskFlags=['understandingCompleted','technologyCompleted','constructionCompleted','designSubmitted','archiveCompleted','experienceCompleted','completed'];
  const taskArrays=['clues','evidence','completedNodes','completedSteps'];
  for(const [era,task] of Object.entries(tasks)){
    if(!eraIds.has(era)||!task||typeof task!=='object'||Array.isArray(task))continue;
    if(Number.isInteger(task.step)&&task.step>0)add(`tasks.${era}.step`);
    for(const key of ['selected','secondSelected','understandingSelected'])if(Number.isInteger(task[key])&&task[key]>=0)add(`tasks.${era}.${key}`);
    for(const key of taskFlags)if(task[key]===true)add(`tasks.${era}.${key}`);
    if(typeof task.designResponse==='string'&&task.designResponse.trim())add(`tasks.${era}.designResponse`);
    if(taskArrays.some(key=>Array.isArray(task[key])&&task[key].length>0))add(`tasks.${era}.records`);
    if(['in-progress','completed','COMPLETED','done'].includes(task.status))add(`tasks.${era}.status`);
  }
  const progression=saved.progression&&typeof saved.progression==='object'&&!Array.isArray(saved.progression)?saved.progression:{};
  // createProgression() seeds a fresh install at 1G/entry so the gallery has
  // an initial pointer. That bootstrap pointer alone is not user exploration.
  if(eraIds.has(progression.currentEra)&&progression.currentEra!=='1G')add('progression.currentEra');
  const entryDialogueId=/^lan\.[1-6]g\.chapter-entry$/;
  if(entryDialogueId.test(String(progression.dialogueProgress?.activeId||'')))add('progression.dialogueProgress.activeId');
  if(Array.isArray(progression.dialogueProgress?.completedIds)&&progression.dialogueProgress.completedIds.some(id=>entryDialogueId.test(String(id))))add('progression.dialogueProgress.completedIds');
  for(const [era,record] of Object.entries(progression.eras||{}))if(eraIds.has(era)&&Array.isArray(record?.nodes)&&record.nodes.some(node=>validNodes.has(node?.key)&&node.nodeId===`${era.toLowerCase()}_${node.key}`&&(node.status==='COMPLETED'||(node.key!=='entry'&&node.status==='ACTIVE')))){add(`progression.eras.${era}.nodes`);break}
  if(eraIds.has(progression.currentEra)&&progression.currentEra==='1G'&&typeof progression.currentNode==='string'&&progression.currentNode!=='1g_entry'&&validNodes.has(progression.currentNode.replace(/^1g_/,'')))add('progression.currentNode');
  if(progression.legacyImportedEras&&hasEra(progression.legacyImportedEras))add('progression.legacyImportedEras');
  if(hasEra(progression.lanMemory?.visitedEras))add('progression.lanMemory.visitedEras');
  return {hasProgress:reasons.length>0,reasons};
}
