function waitFor3DViewer(timeout=8000){
  const viewer=window.CommunicationsHistory3D;
  if(viewer?.mount)return Promise.resolve(viewer);
  const status=window.CommsArchive3DStatus||{};
  if(status.status==='failed')return Promise.reject(new Error(status.reason||'archive3d.js模块加载失败。'));
  console.info('ARCHIVE3D_WAIT_API',{timeout,stage:status.stage||'script-not-registered'});
  return new Promise((resolve,reject)=>{
    let settled=false;
    const cleanups=[];
    const finish=(error,value)=>{
      if(settled)return;
      settled=true;
      clearTimeout(timer);
      cleanups.forEach(remove=>remove());
      if(error)reject(error);else resolve(value);
    };
    const listen=(type,handler)=>{window.addEventListener(type,handler);cleanups.push(()=>window.removeEventListener(type,handler))};
    const tryResolve=()=>{
      const api=window.CommunicationsHistory3D;
      if(api?.mount){console.info('ARCHIVE3D_API_READY',{stage:window.CommsArchive3DStatus?.stage||api.status});finish(null,api);return true}
      return false;
    };
    listen('comms-archive-three-api-ready',tryResolve);
    listen('comms-archive-three-script-error',()=>finish(new Error(window.CommsArchive3DStatus?.reason||'archive3d.js脚本请求或执行失败。')));
    listen('comms-archive-three-module-error',()=>{
      if(window.CommunicationsHistory3D?.mount)finish(null,window.CommunicationsHistory3D);
      else finish(new Error(window.CommsArchive3DStatus?.reason||'本地Three.js模块导入失败。'));
    });
    const timer=setTimeout(()=>{
      if(tryResolve())return;
      const latest=window.CommsArchive3DStatus||{};
      const script=document.querySelector('script[src*="assets/js/archive3d.js"]');
      const scriptState=script?`脚本元素已存在（${script.src||'相对路径'}）`:'未找到archive3d.js脚本元素';
      const message=latest.reason||`等待 ${timeout} 毫秒后仍未注册 CommunicationsHistory3D 接口；${scriptState}。请检查模块脚本是否执行、路径/MIME类型及浏览器模块支持。`;
      console.error('ARCHIVE3D_API_TIMEOUT',{stage:latest.stage||'api-not-registered',reason:message});
      finish(new Error(message));
    },timeout);
    tryResolve();
  });
}
