function experienceTask(era){state.tasks[era]||={};return state.tasks[era]}
function press2GSmsKey(key){const task=experienceTask('2G'),draft=task.smsComposer||{text:'',pendingKey:'',cycle:0,lastTapAt:0},letters={1:'.,?!',2:'ABC',3:'DEF',4:'GHI',5:'JKL',6:'MNO',7:'PQRS',8:'TUV',9:'WXYZ'};const commit=()=>{if(draft.pendingKey)draft.text+=(letters[draft.pendingKey]||'')[draft.cycle]||'';draft.pendingKey='';draft.cycle=0};if(key==='clear'){draft.text='';draft.pendingKey='';draft.cycle=0}else if(key==='back'){if(draft.pendingKey){draft.pendingKey='';draft.cycle=0}else draft.text=draft.text.slice(0,-1)}else if(key==='0'){commit();draft.text+=' '}else if(letters[key]){const now=Date.now();if(draft.pendingKey===key&&now-draft.lastTapAt<1000)draft.cycle=(draft.cycle+1)%letters[key].length;else{commit();draft.pendingKey=key;draft.cycle=0}draft.lastTapAt=now}else return false;task.smsComposer=draft;task.smsDraft=draft.text+(draft.pendingKey?(letters[draft.pendingKey][draft.cycle]||''):'');save();render();return true}
function commit2GSmsCharacter(){const task=experienceTask('2G'),draft=task.smsComposer||{text:'',pendingKey:'',cycle:0,lastTapAt:0};if(draft.pendingKey){const letters={1:'.,?!',2:'ABC',3:'DEF',4:'GHI',5:'JKL',6:'MNO',7:'PQRS',8:'TUV',9:'WXYZ'};draft.text+=(letters[draft.pendingKey]||'')[draft.cycle]||'';draft.pendingKey='';draft.cycle=0;task.smsComposer=draft;task.smsDraft=draft.text;save();render()}return true}
function submit2GSmsDraft(trigger){const task=experienceTask('2G'),draft=String(task.smsDraft||'').trim(),scenario=window.CommsArchiveExperience?.get('2G',trigger);if(!scenario)return false;if(!draft){showInteractionNotice('先用数字键盘编辑一条短信，再提交发送。');return false}if(scenario.step===0){task.smsSubmitted=true;task.smsDeliveryDelayed=true;save();return advanceExperienceInteraction('2G',trigger)}if(!task.smsRelayChecked){showInteractionNotice('请先检查服务中心的转发状态；当前模拟消息仍在等待转发。');return false}task.smsRetried=true;save();return advanceExperienceInteraction('2G',trigger)}
function check2GSmsRelay(){const task=experienceTask('2G');task.smsRelayChecked=true;task.smsRelayFeedback='服务中心的模拟转发路由已核对；消息可以重新提交。';save();render();return true}
function set3GNetworkCondition(value){if(!['constrained','clear'].includes(value))return false;const task=experienceTask('3G');task.mobileDataCondition=value;save();render();return true}
function set3GNetworkPath(value){if(!['wired-reference','wireless'].includes(value))return false;const task=experienceTask('3G');task.mobileDataPath=value;if(value==='wired-reference')task.imageWaited=true;save();render();return true}
function run3GPageStep(trigger){const task=experienceTask('3G'),scenario=window.CommsArchiveExperience?.get('3G',trigger),path=task.mobileDataPath||'wireless';if(!scenario)return false;if(scenario.step===1&&path==='wireless'&&task.mobileDataCondition!=='clear'&&!task.imageWaited){task.imageWaited=true;task.imageWaitFeedback='图片请求已提交，数据仍在传输。本模拟不使用虚构网速数值；等待阶段用来表现内容大小与无线网络条件对体验的影响。';save();render();return true}if(scenario.step===1&&(path==='wired-reference'||task.mobileDataCondition==='clear'))task.imageWaited=true;return advanceExperienceInteraction('3G',trigger)}
function set4GVideoOption(field,value){if(!['quality','network'].includes(field))return false;const task=experienceTask('4G');if(field==='quality'&&!['low','standard','high'].includes(value))return false;if(field==='network'&&!['clear','busy'].includes(value))return false;task[`video${field==='quality'?'Quality':'Network'}`]=value;save();render();return true}
function run4GVideoStep(trigger){const task=experienceTask('4G'),scenario=window.CommsArchiveExperience?.get('4G',trigger);if(!scenario)return false;if(scenario.step===1&&task.videoNetwork==='busy'&&task.videoQuality==='high'){if(!task.videoBufferObserved){task.videoBufferObserved=true;task.videoBufferQuality='high';task.videoBufferNetwork='busy';task.videoBufferFeedback='当前模拟条件下出现缓冲。网络负荷与画质需求不匹配；这只是定性体验模拟，不对应某个真实网速或历史测速数据。';save();render();return true}if(task.videoBufferQuality===task.videoQuality&&task.videoBufferNetwork===task.videoNetwork){showInteractionNotice('当前条件仍与刚才缓冲时相同；尝试降低画质或切换模拟网络条件后再播放。');return false}}if(scenario.step===1)task.videoPlayed=true;save();return advanceExperienceInteraction('4G',trigger)}
function set5GControlMode(value){if(!['general','responsive'].includes(value))return false;experienceTask('5G').controlMode=value;save();render();return true}
function run5GControlStep(trigger){const task=experienceTask('5G'),scenario=window.CommsArchiveExperience?.get('5G',trigger);if(!scenario)return false;if(scenario.step===1&&task.controlMode!=='responsive'&&!task.controlWaitingObserved){task.controlWaitingObserved=true;task.controlFeedback='模拟控制台仍在等待响应。调整配置后可重试；这不代表真实5G网络能保证固定时延。';save();render();return true}if(scenario.step===1){task.controlCompleted=true;task.controlFeedback='模拟机械臂已完成本次控制动作；实际控制还依赖设备、控制系统与安全保护。';save()}return advanceExperienceInteraction('5G',trigger)}
function set6GResearchParameter(name,value){if(!['communication','sensing','computing'].includes(name))return false;const task=experienceTask('6G');task.researchParameters||={communication:50,sensing:50,computing:50};task.researchParameters[name]=Math.max(0,Math.min(100,Number(value)||0));task.researchParameterAdjusted=true;save();const summary=document.getElementById('6gResearchSummary'),output=document.getElementById(`research-${name}-value`);if(summary)summary.textContent=researchTradeoffText(task.researchParameters);if(output)output.textContent=String(task.researchParameters[name]);return true}
function researchTradeoffText(values){if(!values)return '调整权重并运行研究情境，观察优先级取舍。';const high=Object.entries(values).sort((a,b)=>b[1]-a[1])[0];return `当前权重更偏向“${({communication:'数据传递',sensing:'环境感知',computing:'边缘计算'})[high[0]]}”。这是研究情境参数，不是已实现的6G性能指标。`}
function run6GResearchStep(trigger){const task=experienceTask('6G'),scenario=window.CommsArchiveExperience?.get('6G',trigger);if(!scenario)return false;if(scenario.step===0&&!task.researchParameterAdjusted){showInteractionNotice('先调整至少一项研究权重，再运行这组未来情境。');return false}if(scenario.step===0)task.researchSampled=true;else task.researchTradeoffCompared=true;save();return advanceExperienceInteraction('6G',trigger)}
function experienceInteractionMarkup(era,node,done){const scenario=window.CommsArchiveExperience?.get(era,node.trigger);if(!scenario)return `<p class="experience-data-error" role="alert">${escapeHtml(node.location||node.trigger)}的互动资料暂未加载；本时代记录不会因此被跳过。</p>`;if(done){const extra=era==='2G'&&node.trigger==='EXPERIENCE_2G_COMPOSE'?`<p>本次编辑内容：${escapeHtml(state.tasks['2G']?.smsDraft||'')}</p><p>接收端回复：“我已经平安到达，不用担心。”</p>`:'';return `<div class="experience-result"><span class="status done">已记录</span><p>${escapeHtml(scenario.result)}</p>${extra}</div>`}const q=String.fromCharCode(39),step=Math.min(scenario.step,scenario.total-1),basic=`<div class="eyebrow">互动模拟 · ${scenario.step}/${scenario.total}</div><strong>${escapeHtml(scenario.title)}</strong><p>${escapeHtml(scenario.prompt)}</p>${scenario.feedback.map(text=>`<p class="experience-feedback">${escapeHtml(text)}</p>`).join('')}`;if(era==='2G'&&node.trigger==='EXPERIENCE_2G_COMPOSE'){const task=state.tasks['2G']||{},draft=task.smsComposer||{text:'',pendingKey:'',cycle:0};return `<div class="experience-simulation sms-simulation">${basic}<label for="smsDraft2G">短信编辑区 · 多次按键输入</label><output id="smsDraft2G" class="sms-draft" aria-live="polite">${escapeHtml(task.smsDraft||'')}<span class="sms-pending">${draft.pendingKey?escapeHtml(({1:'.,?!',2:'ABC',3:'DEF',4:'GHI',5:'JKL',6:'MNO',7:'PQRS',8:'TUV',9:'WXYZ'})[draft.pendingKey]?.[draft.cycle]||''):''}</span></output><div class="sms-keypad">${['1','2','3','4','5','6','7','8','9','clear','0','back'].map(key=>`<button type="button" onclick="press2GSmsKey('${key}')" aria-label="${key==='clear'?'清空短信':key==='back'?'删除字符':key==='0'?'输入空格':`数字${key}，多次按键选择字符`}">${key==='clear'?'清空':key==='back'?'⌫':key==='0'?'0 / 空格':`${key} ${({1:'. , ? !',2:'ABC',3:'DEF',4:'GHI',5:'JKL',6:'MNO',7:'PQRS',8:'TUV',9:'WXYZ'})[key]||''}`}</button>`).join('')}</div><p class="muted">同一数字键在短时间内重复点击可切换字母；也可点击“确定字符”。这是简化的多次按键输入。</p><button class="btn ghost" type="button" onclick="commit2GSmsCharacter()">确定字符</button>${scenario.step===0?`<button class="btn secondary" type="button" onclick="submit2GSmsDraft('${node.trigger}')">提交短信 →</button>`:`<div class="feedback"><strong>消息暂未抵达</strong><br>${escapeHtml(task.smsRelayFeedback||'本次模拟中，消息已提交但服务中心尚未转发。')}</div><button class="btn secondary" type="button" onclick="check2GSmsRelay()">检查短信服务中心转发</button><button class="btn" type="button" onclick="submit2GSmsDraft('${node.trigger}')">修正后重新发送 →</button>`}</div>`}
if(era==='3G'&&node.trigger==='CLICK_FIRST_MOBILE_INTERNET'){const task=state.tasks['3G']||{},condition=task.mobileDataCondition||'constrained',path=task.mobileDataPath||'wireless';return `<div class="experience-simulation mobile-web-simulation">${basic}<div class="network-condition-picker"><span>连接路径</span><button type="button" aria-pressed="${path==='wired-reference'}" onclick="set3GNetworkPath('wired-reference')">有线参考（固定终端）</button><button type="button" aria-pressed="${path==='wireless'}" onclick="set3GNetworkPath('wireless')">3G无线接入（手机）</button></div><p class="muted">有线项是固定终端参考；手机项模拟通过3G无线接入访问移动服务。以下只用“较顺畅 / 等待”作为本地教学参数，不代表某地区的历史测速。</p><div class="network-condition-picker"><span>模拟网络负荷</span><button type="button" aria-pressed="${condition==='constrained'}" onclick="set3GNetworkCondition('constrained')">负荷较高</button><button type="button" aria-pressed="${condition==='clear'}" onclick="set3GNetworkCondition('clear')">条件较宽松</button></div><div class="retro-web-screen"><b>移动网页测试</b><p>访问方式：${path==='wired-reference'?'有线参考路径':'手机3G无线接入'}</p><p>文字：${scenario.step?'已显示':'等待请求'}</p><p>图片：${scenario.step>1?'已显示':task.imageWaited?'等待继续或重新请求':'等待请求'}</p></div>${scenario.step===0?`<button class="btn secondary" type="button" onclick="run3GPageStep('${node.trigger}')">请求文字网页 →</button>`:scenario.step===1&&!task.imageWaited&&path==='wireless'&&condition!=='clear'?`<p class="experience-feedback">${escapeHtml(task.imageWaitFeedback||'图像数据仍在传输，文字先到达。')}</p><button class="btn secondary" type="button" onclick="run3GPageStep('${node.trigger}')">继续等待图像 →</button>`:`<button class="btn secondary" type="button" onclick="run3GPageStep('${node.trigger}')">请求并查看页面图片 →</button>`}<p class="muted">本地定性模拟，不展示虚构的网速或时延数值；真实体验还会受到无线环境、终端和服务内容影响。</p></div>`}
if(era==='4G'&&node.trigger==='EXPERIENCE_4G_VIDEO'){const task=state.tasks['4G']||{},quality=task.videoQuality||'standard',network=task.videoNetwork||'clear';return `<div class="experience-simulation video-simulation">${basic}<div class="video-mock-frame"><span>移动视频 · ${quality==='high'?'高':quality==='low'?'低':'标准'}画质</span><div class="video-scene">▶</div><small>${task.videoBufferObserved?'出现缓冲':'等待播放'}</small></div><label>选择画质<select onchange="set4GVideoOption('quality',this.value)"><option value="low" ${quality==='low'?'selected':''}>低</option><option value="standard" ${quality==='standard'?'selected':''}>标准</option><option value="high" ${quality==='high'?'selected':''}>高</option></select></label><label>模拟网络负荷<select onchange="set4GVideoOption('network',this.value)"><option value="clear" ${network==='clear'?'selected':''}>较宽松</option><option value="busy" ${network==='busy'?'selected':''}>较繁忙</option></select></label>${task.videoBufferObserved?`<p class="experience-feedback">${escapeHtml(task.videoBufferFeedback)}</p>`:''}<button class="btn secondary" type="button" onclick="run4GVideoStep('${node.trigger}')">${scenario.step===0?'选择视频片段 →':'播放并检查连续性 →'}</button><p class="muted">这是质量与负荷的定性示意，不代表某一地区或年份的实测网速。</p></div>`}
if(era==='5G'&&node.trigger==='EXPERIENCE_5G_INDUSTRY'){const task=state.tasks['5G']||{},mode=task.controlMode||'general';return `<div class="experience-simulation robot-simulation">${basic}<div class="robot-control-panel"><strong>远程机械臂 · 示意控制台</strong><div class="robot-arm ${task.controlCompleted?'moved':''}" aria-label="模拟机械臂">▰━━●</div><div class="network-condition-picker"><button type="button" aria-pressed="${mode==='general'}" onclick="set5GControlMode('general')">普通响应情境</button><button type="button" aria-pressed="${mode==='responsive'}" onclick="set5GControlMode('responsive')">低时延配置情境</button></div><p>${escapeHtml(task.controlFeedback||'先读取设备状态，再发送两步控制指令。')}</p>${scenario.step===0?`<button class="btn secondary" type="button" onclick="run5GControlStep('${node.trigger}')">读取机械臂状态 →</button>`:task.controlWaitingObserved&&mode!=='responsive'?`<button class="btn secondary" type="button" onclick="set5GControlMode('responsive')">调整配置后重试</button><button class="btn" type="button" onclick="run5GControlStep('${node.trigger}')">重试控制指令 →</button>`:`<button class="btn secondary" type="button" onclick="run5GControlStep('${node.trigger}')">${mode==='responsive'?'发送控制指令并观察响应 →':'发送控制指令 →'}</button>`}</div><p class="muted">网络响应仅作示意，5G不保证所有部署和应用环境都具有固定低时延。</p></div>`}
if(era==='6G'&&node.trigger==='EXPERIENCE_6G_ENVIRONMENT'){const task=state.tasks['6G']||{},values=task.researchParameters||{communication:50,sensing:50,computing:50};return `<div class="experience-simulation research-simulation">${basic}<p class="muted">未来研究情境模拟：调整关注权重并观察取舍，不对应已经实现的6G产品能力。</p>${[['communication','通信传递'],['sensing','环境感知'],['computing','边缘计算']].map(([key,label])=>`<label>${label}权重 <input type="range" min="0" max="100" value="${values[key]}" oninput="set6GResearchParameter('${key}',this.value)"><output id="research-${key}-value">${values[key]}</output></label>`).join('')}<p id="6gResearchSummary" class="research-tradeoff">${escapeHtml(researchTradeoffText(values))}</p><button class="btn secondary" type="button" onclick="run6GResearchStep('${node.trigger}')">${scenario.step===0?'运行这组未来情境 →':'对照权衡并记录研究观察 →'}</button><p class="muted">参数只是本项目用于解释权衡的抽象权重；6G仍处于研究发展阶段。</p></div>`}
return `<div class="experience-simulation"><div class="eyebrow">互动模拟 · ${scenario.step}/${scenario.total}</div><strong>${escapeHtml(scenario.title)}</strong><p>${escapeHtml(scenario.prompt)}</p>${scenario.feedback.map(text=>`<p class="experience-feedback">${escapeHtml(text)}</p>`).join('')}<button class="btn secondary" onclick="advanceExperienceInteraction(${q+era+q},${q+node.trigger+q})">${escapeHtml(scenario.actions[step])} →</button></div>`}
function completeEraExperienceNode(era,nodeId){const story=window.CommsArchiveLan?.getExperienceStory?.(era)||window[`ExperienceStory${era}`],node=story?.nodes?.find(item=>item.trigger===nodeId);if(!node)return false;const alreadyDone=(window.CommsArchiveLan?.LanMemory?.completedExperienceNodes||[]).includes(nodeId);if(!alreadyDone&&!window.CommsArchiveLan?.completeExperienceNode?.(nodeId,era))return false;state.logs??=[];if(node.reward&&!state.logs.some(log=>log.id===node.id))state.logs.push({id:node.id,era,type:'时代体验记录',title:node.reward,time:new Date().toISOString()});const saved=save();render();if(!saved)showInteractionNotice('体验操作已完成，但本地存档暂不可写入；请检查浏览器存储后重试。');return saved}
function advanceExperienceInteraction(era,nodeId){const result=window.CommsArchiveExperience?.advance(era,nodeId);if(!result?.ok)return false;if(result.saved===false)showInteractionNotice('互动反馈已显示，但浏览器未能保存这一步；完成的体验记录仍会单独保存。');if(result.complete)return completeEraExperienceNode(era,nodeId);render();return true}
function renderExperienceStory(e,era,lead,disclaimer=''){const story=window.CommsArchiveLan?.getExperienceStory?.(era)||window[`ExperienceStory${era}`];if(!story?.nodes?.length)throw new Error(`${era}用户体验资料未加载，无法渲染生活现场。`);const done=new Set(window.CommsArchiveLan?.LanMemory?.completedExperienceNodes||[]),lifeNode=progression.state.eras?.[era]?.nodes?.find(node=>node.key==='life'),recordId=`era-impact-${era.toLowerCase()}`,legacyRecorded=lifeNode?.status==='COMPLETED'||state.logs?.some(item=>item.id===recordId),allDone=story.nodes.every(node=>done.has(node.trigger))||legacyRecorded;return `<div class="eyebrow">生活现场 / ${escapeHtml(era)}</div><h3>${escapeHtml(story.title)}</h3><section class="guided-section"><h4>普通用户的通信场景</h4><p>${escapeHtml(e.moment)}</p><p>${escapeHtml(e.record)}</p><p>${escapeHtml(lead)}</p>${disclaimer?`<p class="muted">${escapeHtml(disclaimer)}</p>`:''}</section><div class="experience-node-list">${story.nodes.map((node,index)=>`<article class="experience-node ${done.has(node.trigger)?'completed':''}"><div><span class="eyebrow">体验节点 0${index+1}</span><h4>${escapeHtml(node.location||node.title||node.id)}</h4><p>${escapeHtml(node.reward||'完成这段时代生活体验。')}</p>${experienceInteractionMarkup(era,node,done.has(node.trigger))}</div></article>`).join('')}</div>${legacyRecorded&&!story.nodes.every(node=>done.has(node.trigger))?'<div class="feedback"><strong>本地存档已保留此前完成的生活体验</strong><br>下面的互动可重新查看，不会撤销原记录。</div>':''}${allDone?`<div class="feedback"><strong>${escapeHtml(era)}体验记录已完成</strong><br>${escapeHtml(era==='6G'?'这是研究情境记录，不代表6G能力已经普遍商用。':'互动结果已写入本地时空日志。')}</div>`:'<p class="muted" id="experience-record-guidance">逐项完成上方互动后，才能记录时代影响并进入归档。</p>'}<button class="btn" aria-describedby="experience-record-guidance" onclick="recordGuidedExperience()">${allDone?'记录时代影响，前往档案出口 →':'检查体验记录条件'}</button></div>`}
function render1GExperience(e){const life=progression.state.eras?.['1G']?.nodes?.find(node=>node.key==='life'),legacy=life?.status==='COMPLETED'||state.logs?.some(item=>item.id==='era-impact-1g');return window.CommsArchive1GPhone?.render(e,legacy)||renderExperienceStory(e,'1G','比较覆盖范围如何影响普通用户拨打移动电话与联系家人。')}
function render2GExperience(e){return renderExperienceStory(e,'2G','跟随一条报平安短信，观察文字如何被编辑、转发并等待阅读。')}
function render3GExperience(e){return renderExperienceStory(e,'3G','通过手机联网、查地图、浏览新闻与图片、请求早期移动视频，观察移动数据如何进入日常生活。交互为本地模拟情境。')}
function complete3GExperience(nodeId){return completeEraExperienceNode('3G',nodeId)}
function recordGuidedExperience(){
 const era=eras[eraIndex]?.id,mode=window.DemoManager?.isActive?.()?'demo':'normal',source='recordGuidedExperience';
 window.InteractionDebugger?.record('BUTTON_HANDLER_START',source,{buttonId:'record-era-impact',era,mode,currentPage:route,currentEra:progression.currentEra?.(),currentNode:progression.currentNode?.()?.nodeId||null});
 if(!era||progression.currentEra?.()!==era){const reason='当前页面与探索进度不一致，请从时代航线重新打开本时代的生活体验。';showInteractionNotice(reason);window.InteractionDebugger?.record('NAVIGATION_BLOCKED',source,{era,mode,reason});return false}
 const story=window.CommsArchiveLan?.getExperienceStory?.(era)||window[`ExperienceStory${era}`]||null,done=new Set(window.CommsArchiveLan?.LanMemory?.completedExperienceNodes||[]),missing=story?.nodes?.length?story.nodes.filter(node=>!done.has(node.trigger)):[];
 if(!story?.nodes?.length){const reason=`${era}体验资料尚未加载，时代影响没有被记录。请重新载入本页后再试。`;showInteractionNotice(reason);window.InteractionDebugger?.record('NAVIGATION_BLOCKED',source,{era,mode,reason});return false}
 state.logs??=[];
 const recordId=`era-impact-${era.toLowerCase()}`,lifeNode=progression.state.eras?.[era]?.nodes?.find(node=>node.key==='life'),existing=state.logs.find(item=>item.id===recordId),alreadyRecorded=lifeNode?.status==='COMPLETED';
 if(alreadyRecorded){let saved=true;if(!existing){const e=eras[eraIndex];state.logs.push({id:recordId,era,type:'时代影响记录',title:`${era}时代影响`,direction:'时代影响',discovery:e.record,time:new Date().toISOString()});saved=save()}render();showInteractionNotice(existing?'这段时代影响已经记录，可以继续完成档案封存。':saved?'已补齐可回看的时代影响记录；可以继续完成档案封存。':'生活体验已完成，但影响记录未能写入本地存档，请检查存储空间后重试。');window.InteractionDebugger?.record(saved?'BUTTON_HANDLER_SUCCESS':'BUTTON_HANDLER_FAILED',source,{buttonId:'record-era-impact',era,mode,alreadyRecorded:true,saved,currentNode:progression.currentNode?.()?.nodeId||null});return saved}
 if(progression.currentNode?.()?.key!=='life'){const reason='请先打开当前时代的生活体验节点，再记录时代影响。';showInteractionNotice(reason);window.InteractionDebugger?.record('BUTTON_HANDLER_FAILED',source,{buttonId:'record-era-impact',era,mode,reason,currentPage:route,currentNode:progression.currentNode?.()?.nodeId||null});return false}
 if(!story.nodes.every(node=>done.has(node.trigger))){const reason=`请先完成${era}用户体验区的全部互动，再记录时代影响。尚未完成：${missing.map(node=>node.location||node.title||node.id).join('、')}。`;showInteractionNotice(reason);window.InteractionDebugger?.record('NAVIGATION_BLOCKED',source,{era,mode,reason,missingNodes:missing.map(node=>node.trigger)});return false}
 const e=eras[eraIndex],record={id:recordId,era,type:'时代影响记录',title:`${era}时代影响`,direction:'时代影响',discovery:e.record,time:new Date().toISOString()},result=progression.recordExperience(record);if(progressionBlock(result)){window.InteractionDebugger?.record('BUTTON_HANDLER_FAILED',source,{buttonId:'record-era-impact',era,mode,reason:result?.reason||'experience_node_blocked'});return false}
 const saved=result.saved!==false;render();showInteractionNotice(saved?'时代影响已记录并保存。现在可以前往时代档案出口。':'生活体验已完成，但时代影响记录未能写入本地存档，请检查存储空间后重试。');window.InteractionDebugger?.record(saved?'BUTTON_HANDLER_SUCCESS':'BUTTON_HANDLER_FAILED',source,{buttonId:'record-era-impact',era,mode,saved,currentNode:progression.currentNode?.()?.nodeId||null,recordId});return saved
}
function flowDiagram(e,active=-1){const v=mediaAssets[e.id],labels=v.flow,colors=[e.color,'#86d9ff','#b49aff','#f2d58d'];return `<svg class="history-diagram" viewBox="0 0 760 250" role="img" aria-label="${e.id} ${v.flowNote}"><defs><linearGradient id="dg${e.id}" x1="0" x2="1"><stop stop-color="${e.color}" stop-opacity=".28"/><stop offset="1" stop-color="#69cfff" stop-opacity=".08"/></linearGradient></defs><rect x="1" y="1" width="758" height="248" rx="18" fill="url(#dg${e.id})" stroke="${e.color}" stroke-opacity=".42"/><path d="M115 103H640" stroke="#8fcde8" stroke-opacity=".55" stroke-width="2" stroke-dasharray="5 8"/>${labels.map((label,i)=>{const x=55+i*178;return `<g class="${i===active?'current':''}" transform="translate(${x} 62)"><rect width="142" height="82" rx="13" fill="#071427" stroke="${colors[i]}" stroke-opacity=".8"/><circle cx="18" cy="18" r="5" fill="${colors[i]}"/><text x="71" y="46" text-anchor="middle" fill="#eef7ff" font-size="15" font-family="sans-serif">${label}</text><text x="71" y="68" text-anchor="middle" fill="#91a8c4" font-size="11" font-family="sans-serif">节点 0${i+1}</text></g>${i<labels.length-1?`<path d="M${x+146} 103h23m-7-6 7 6-7 6" fill="none" stroke="#a8dff2" stroke-width="2"/>`:''}`}).join('')}<text x="380" y="196" text-anchor="middle" fill="#a9bfd8" font-size="13" font-family="sans-serif">通信简史 · ${e.id} 技术流程示意</text></svg><div class="diagram-mobile-flow">${labels.map((label,i)=>`<div class="flow-node ${i===active?'current':''}" style="--node-color:${colors[i]}"><span>节点 0${i+1}</span><strong>${label}</strong></div>${i<labels.length-1?'<span class="flow-down">↓</span>':''}`).join('')}</div>`}
function imageSupplement(id,compact=false){const e=eras.find(x=>x.id===id),v=mediaAssets[id];if(!e||!v)return '';return `<section class="history-media${compact?' compact':''}" aria-label="${e.id}图片与技术原理补充"><div class="media-heading"><div><div class="eyebrow">VISUAL COLLECTION · ${e.id}</div><h3>馆藏图像与技术原理</h3></div><span class="media-type">图片为正文补充</span></div><div class="media-grid">${v.photo?`<figure class="media-figure"><img loading="lazy" src="${v.photo}" alt="${v.photoTitle}" tabindex="0" onclick="openImageViewer('${v.photo}','${escapeHtml(v.photoTitle)}')" onkeydown="if(event.key==='Enter'||event.key===' ')openImageViewer('${v.photo}','${escapeHtml(v.photoTitle)}')" onerror="imageLoadFallback(this)"/><div class="exhibit-image-fallback" hidden>馆藏图片暂时无法加载；正文仍可阅读，请检查本地素材路径。</div><figcaption><strong>${v.photoTitle}</strong><span>${v.photoNote}</span><small>素材类型：${v.photoType}</small><span>署名：${v.photoCredit}</span><span>许可：<a href="${v.photoLicenseUrl}" target="_blank" rel="noopener noreferrer">${v.photoLicense} ↗</a> · <a href="${v.photoSource}" target="_blank" rel="noopener noreferrer">来源记录 ↗</a></span></figcaption></figure>`:`<figure class="media-figure concept-figure"><div class="future-scene" role="img" aria-label="${v.photoTitle}"><div class="future-research-steps"><span>模拟环境</span><i aria-hidden="true">→</i><span>感知数据</span><i aria-hidden="true">→</i><span>数字模型</span></div><span class="future-label">DIGITAL TWIN · RESEARCH SCENARIO</span></div><figcaption><strong>${v.photoTitle}</strong><span>${v.photoNote}</span><small>素材类型：原创未来概念图</small><span>${v.photoCredit}</span></figcaption></figure>`}<figure class="media-figure diagram-figure"><div class="diagram-wrap">${flowDiagram(e)}</div><figcaption><strong>${e.id}技术流程示意</strong><span>${v.flowNote}</span><small>素材类型：本项目原创技术原理示意图</small></figcaption></figure></div></section>`}
function card(e,i){const status=eraStatus(e),taskStatus=eraTaskStatus(e),demoOpen=window.DemoManager?.isActive?.()&&window.DemoManager.state.routeMode!=='recommended',access=demoOpen?{ok:true}:progressionEraAllowed(e.id);return `<article class="card era-card" style="--glow:${e.color}"><div class="era-top"><span class="era-no">${e.id}</span><span class="status ${status==='已完成'?'done':status==='探索中'?'active':''}">${status}</span></div><div class="mono">${e.year}</div><h3>${e.title}</h3><div class="keywords">${e.keys}</div><p class="era-task-state"><span>待办</span>${taskStatus}</p><div class="mini-scene"></div>${access.ok?'':`<p class="era-lock-reason" id="era-lock-${e.id}" role="status">${escapeHtml(access.reason||'请先完成前序时代的调查并封存档案。')}</p>`}<button id="eraEntry${e.id}" data-button-id="era-entry-${e.id}" class="btn secondary" ${access.ok?'':'disabled title="'+escapeHtml(access.reason||'请先完成前序时代的调查并封存档案。')+'" aria-describedby="era-lock-'+e.id+'"'} onclick="enterEra(${i})">${demoOpen?'演示此时代 →':access.ok?'进入时代 →':'时代尚未开放'}</button></article>`}
function homeEraCard(e,i){const st=eraStatus(e),demoOpen=window.DemoManager?.isActive?.()&&window.DemoManager.state.routeMode!=='recommended',access=demoOpen?{ok:true}:progressionEraAllowed(e.id);return '<button class="home-era '+(st==='已完成'?'done':st==='探索中'?'active':'')+'" '+(access.ok?'':'disabled title="'+escapeHtml(access.reason)+'"')+' onclick="enterEra('+i+')"><b>'+e.id+'</b><span>'+escapeHtml(e.year)+'</span><strong>'+escapeHtml(e.title)+'</strong><small>'+escapeHtml(e.theme)+'</small><small>'+escapeHtml(e.keys)+'</small><em>'+st+' · '+(demoOpen?'演示可进入':access.ok?'可进入':'锁定')+'</em></button>'}
function home(){const formalState=homeFormalState(),progressStatus=homeFormalProgressStatus(formalState),hasProgress=progressStatus.hasProgress,completed=Array.isArray(formalState.completed)?formalState.completed:[],visited=Array.isArray(formalState.visited)?formalState.visited:[],order=Array.isArray(formalState.order)?formalState.order:[],next=[...order,...visited].reverse().find(id=>eras.some(era=>era.id===id)&&!completed.includes(id)),buttonLabel=hasProgress?'继续探索':'开始探索',resumeLabel=hasProgress?(next?'继续 '+next+' 调查':'已保存探索进度；点击继续最近的有效位置。'):'首次进入将从序章开始，随后直接进入1G《失联的呼叫》。';return `<section class="page home-page"><div class="hero"><div class="hero-copy"><div class="eyebrow">HISTORY OF MOBILE COMMUNICATIONS / 01—06</div><h1>通信简史：从1G到6G</h1><p class="build-version">Build ${APP_VERSION}</p><p class="lead">穿越移动通信发展历程</p><p class="home-intro">与澜一起回顾1G—5G历史，探索6G研究展望：查看展品、理解技术原理、调查时代现场，并记录通信如何改变人的生活。</p><div class="actions home-primary-actions"><button id="homeContinueExplore" class="btn home-primary" data-button-id="home-continue-explore" onclick="homePrimaryAction()">✦ ${buttonLabel} →</button><button class="btn secondary" onclick="openDemoRoutePicker()">比赛演示</button></div><p class="home-note" id="homeResumeHint">${escapeHtml(resumeLabel)}</p><p class="home-note">比赛演示使用独立进度，不会写入日常探索存档。时代航线、文明档案和通信知识搜索可从顶部导航进入。</p></div><div class="hero-art" role="img" aria-label="六代通信时代视觉预览"><div class="portal"></div><div class="portal-core"></div><div class="orbit"></div><div class="orbit o2"></div><div class="scan"></div><span class="holo-label l1">六代通信时代</span><span class="holo-label l2">历史资料 · 技术原理 · 调查任务</span></div></div><div class="review-principle"><span class="eyebrow">调查路径</span><strong>发现展品 → 理解技术 → 分析问题 → 收集证据</strong><span>历史正文、展品、任务和档案继续保留在探索流程中。</span></div></section>`}
