function technicalChallengeSection(e){if(e?.id!=='1G')return '';return `<details id="technicalChallenge1G" class="technical-challenge"><summary>技术难点：覆盖、容量与移动中的无线链路</summary><p><strong>遇到了什么问题：</strong>蜂窝移动网络需要在有限无线频谱内安排多个小区服务用户。手机移动时，无线信道会随位置和环境改变，通话质量与控制信令也需要维持。</p><p><strong>为什么难：</strong>扩大覆盖、增加可服务用户数、控制同频干扰和保持移动中的通话连续性彼此牵连；单纯增加发射功率或靠近基站并不能解决所有情况。</p><p><strong>采用的办法：</strong>以AMPS蜂窝系统的早期设计为例，网络通过小区化部署和频率复用提高频谱利用率，并由网络控制完成移动中的小区切换。不同国家和1G系统的实现细节并不完全相同。</p><p><strong>带来的变化：</strong>蜂窝网络扩大了移动语音服务的部署能力，同时让覆盖规划、容量与切换成为持续的网络工程问题。</p><p class="muted">历史技术说明以AMPS论文为例，不代表所有1G网络采用相同配置。来源：<a href="https://www.nokia.com/bell-labs/publications-and-media/publications/advanced-mobile-phone-service-the-cellular-concept/" target="_blank" rel="noopener noreferrer">Bell System Technical Journal（1979）· The Cellular Concept</a>；<a href="https://www.nokia.com/bell-labs/publications-and-media/publications/advanced-mobile-phone-service-voice-and-data-transmission/" target="_blank" rel="noopener noreferrer">Bell System Technical Journal（1979）· Voice and Data Transmission</a>.</p></details>`}
function mountExhibitTechnicalChallenge(e){if(e?.id!=='1G'||currentExhibitTab!=='technology')return;const host=document.querySelector('.exhibit-content');if(host&&!host.querySelector('#technicalChallenge1G'))host.insertAdjacentHTML('beforeend',technicalChallengeSection(e))}
