function applyArchiveImport(data){const format=data?.format,legacy=format==='comms-archive-v1',lan=window.CommsArchiveLan;if(!legacy&&(format!=='comms-archive-v2'||data.version!==2))throw Error('存档版本不受支持');if(!validateImportedArchiveState(data.state,legacy))throw Error('主进度格式不正确或包含未知时代编号');if(typeof lan?.validateJourneyData!=='function'||typeof lan?.importJourneyData!=='function'||typeof lan?.exportJourneyData!=='function'||typeof lan?.createEmptyJourneyData!=='function')throw Error('澜的探索记录模块暂不可用');const journey=legacy?lan.createEmptyJourneyData():data.journey;if(!lan.validateJourneyData(journey))throw Error('剧情探索记录或年代总结格式不正确');if(legacy&&!confirm('这是旧版 v1 存档，只包含主进度，不含澜对白探索记录、剧情历史和年代总结。继续导入会以该文件替换当前探索记录；缺失的旧记录无法恢复。音量、亮度等个人设置会保留。是否继续？'))return false;const previousState=state,previousJourney=lan.exportJourneyData();state=normalizeSavedState(data.state);try{rebindProgression()}catch(error){state=previousState;rebindProgression();throw error}if(!save()){state=previousState;rebindProgression();save();throw Error('主进度未能保存，原有存档已恢复')}if(!lan.importJourneyData(journey)){state=previousState;rebindProgression();save();throw Error('澜的探索记录未能恢复，主进度已回滚')}try{render()}catch(error){state=previousState;rebindProgression();save();lan.importJourneyData(previousJourney);throw Error('导入后的页面更新失败，已尝试恢复原存档：'+(error?.message||String(error)))}alert(legacy?'主进度已导入。此 v1 文件不含澜对白探索记录、剧情历史和年代总结，这些内容未从文件恢复；声音、亮度等个人设置已保留。':'探索进度、澜对白记录、剧情历史和年代总结已完整恢复；声音、亮度等个人设置保持当前值。');return true}
async function handleArchiveImport(ev){const f=ev.target.files?.[0];if(!f)return false;try{return applyArchiveImport(JSON.parse(await f.text()))}catch(error){alert(`存档导入失败：${error?.message||'文件无法读取'}。未确认的导入不会修改原存档。`);return false}finally{ev.target.value=''}}
