  firstExplorationProloguePending=false;reviewGuideActive=false;reviewGuideStage=0;
  taskStep=0;selected=null;secondSelected=null;understandingSelected=null;designResponse='';
  currentExhibitId=null;currentExhibitItemId=null;currentExhibitSource='chapter';currentExhibitTab='history';
  archiveReturnContext=null;pendingRouteScrollRestore=null;suppressLanAutoDialogueOnce=false;
