function quizRender(){
const box=document.querySelector('#quizBox');if(!box)return;if(!quizSession)quizSession=normalizeQuizSession(quizStore.loadSession()||window.CommsArchiveQuiz.createSession());
if(quizSession.completed){clearTimeout(quizAutoTimer);const score=window.CommsArchiveQuiz.score(quizSession);const perfect=score===10;if(perfect&&!quizSession.celebrated){quizSession.celebrated=true;quizPersist();window.CommsArchiveLan?.onQuizPerfect()}
let review='';if(quizSession.reviewExpanded){review='<div class="quiz-review">'+quizSession.answers.map((a,i)=>{const q=window.CommsArchiveQuiz.questions.find(x=>x.id===a.questionId);return '<article><b>'+(i+1)+'. '+escapeHtml(q.question)+'</b><p>'+(a.correct?'回答正确':'你的选择：'+escapeHtml(q.options[a.selected]))+' · 正确答案：'+escapeHtml(q.options[a.answer])+'</p><small>'+escapeHtml(a.explanation)+'</small></article>'}).join('')+'</div>'}
box.innerHTML='<div class="eyebrow">本轮探索完成</div><h2>得分 '+score+' / 10</h2><p class="lead">正确率 '+(score*10)+'%</p>'+(perfect?'<div class="quiz-perfect"><b>澜</b>：“完美回答！看来你已经真正理解这一代通信技术的发展。”<span>已获得徽章：知识探索者</span></div>':'<p class="answer">继续在展厅中观察展品、阅读技术原理，随时可以再来一轮。</p>')+'<div class="actions"><button class="btn secondary" onclick="toggleQuizReview()">'+(quizSession.reviewExpanded?'收起答案与解析':'查看每题正确答案与解析')+'</button><button class="btn" onclick="startQuiz()">再答一轮</button><button class="btn secondary" onclick="go(\'archive\')">查看文明档案</button></div>'+review;return}
const q=window.CommsArchiveQuiz.questions.find(item=>item.id===(quizSession.answerSubmitted&&quizSession.feedback?quizSession.feedback.questionId:quizSession.questionIds[quizSession.answers.length]));if(!q){quizSession=normalizeQuizSession(window.CommsArchiveQuiz.createSession());quizPersist();return quizRender()}const answered=!!quizSession.answerSubmitted&&!!quizSession.feedback;const questionNumber=Math.min(10,Math.max(1,quizSession.answers.length+(answered?0:1)));if(answered&&!quizSession.explanationExpanded)scheduleQuizAdvance();else clearTimeout(quizAutoTimer);
const explanation=answered&&quizSession.explanationExpanded?'<div class="quiz-explanation"><p><b>正确答案：</b>'+escapeHtml(q.options[quizSession.feedback.answer])+'</p><p>'+escapeHtml(quizSession.feedback.explanation)+'</p></div>':'';
box.innerHTML='<div class="eyebrow">QUESTION '+String(questionNumber).padStart(2,'0')+' / 10</div><h3>'+escapeHtml(q.question)+'</h3><div class="quiz-options">'+q.options.map((option,i)=>{const correct=answered&&i===quizSession.feedback.answer,wrong=answered&&i===quizSession.feedback.selected&&!quizSession.feedback.correct;return '<button type="button" class="quiz-option '+(correct?'quiz-correct':'')+' '+(wrong?'quiz-wrong':'')+' '+(quizSession.selected===i?'selected':'')+'" '+(answered?'disabled':'')+' onclick="selectQuizOption('+i+')"><span>'+'ABCD'[i]+'</span>'+escapeHtml(option)+'</button>'}).join('')+'</div>'+(answered?'<div class="quiz-quick-feedback '+(quizSession.feedback.correct?'is-correct':'is-wrong')+'" role="status">'+(quizSession.feedback.correct?'回答正确':'本题未答对')+'</div>'+explanation+'<div class="actions"><button class="btn secondary" onclick="revealQuizAnswer()">'+(quizSession.explanationExpanded?'收起答案解析':'查看答案解析')+'</button><button class="btn" onclick="nextQuizQuestion()">下一题 →</button></div><span class="quiz-auto-note">稍后自动进入下一题；查看解析可暂停，或直接点击“下一题”。</span>':'<p class="muted">选择一个选项，系统会立即判断。</p>')+(!quizStorageOk?'<p class="storage-note">本地存储不可用，答题进度仅保留在当前页面。</p>':'')}
function selectQuizOption(index){if(!quizSession||quizSession.answerSubmitted||quizSession.feedback)return;quizSession.selected=index;submitQuizAnswer(index)}
function submitQuizAnswer(index=quizSession?.selected){if(!quizSession||quizSession.answerSubmitted||!Number.isInteger(index))return false;quizSession.selected=index;quizSession.feedback=window.CommsArchiveQuiz.recordAnswer(quizSession,index);if(!quizSession.feedback)return false;quizSession.answerSubmitted=true;quizSession.explanationExpanded=false;quizSession.lastAdvancedQuestionId='';if(quizSession.completed)saveCompletedQuizRecordOnce();quizPersist();quizRender();return true}
function scheduleQuizAdvance(){clearTimeout(quizAutoTimer);quizAutoTimer=setTimeout(()=>advanceQuizQuestion('auto'),3000)}
function revealQuizAnswer(){if(!quizSession?.answerSubmitted||!quizSession.feedback||quizSession.completed)return false;clearTimeout(quizAutoTimer);quizSession.explanationExpanded=!quizSession.explanationExpanded;quizPersist();quizRender();return true}
function toggleQuizReview(){if(!quizSession?.completed)return;quizSession.reviewExpanded=!quizSession.reviewExpanded;quizPersist();quizRender()}
function advanceQuizQuestion(source='manual'){const session=quizSession,questionId=session?.feedback?.questionId;if(!session?.answerSubmitted||!questionId||session.completed||session.lastAdvancedQuestionId===questionId)return false;clearTimeout(quizAutoTimer);session.lastAdvancedQuestionId=questionId;session.selected=null;session.feedback=null;session.answerSubmitted=false;session.explanationExpanded=false;delete session.showAnswer;quizPersist();window.InteractionDebugger?.record('QUIZ_ADVANCE','advanceQuizQuestion',{source,questionId,answered:session.answers.length});quizRender();return true}
function nextQuizQuestion(){return advanceQuizQuestion('manual')}
function deleteQuizRecord(id){if(typeof id!=='string'||!id)return false;if(!quizStore.getRecords().some(record=>record.id===id)){showInteractionNotice('这条答题记录已不存在，列表已更新。');render();return false}if(!confirm('删除这条答题记录？此操作不会影响其他记录或当前答题解析。'))return false;if(!quizStore.deleteRecord(id)||quizStore.getRecords().some(record=>record.id===id)){showInteractionNotice('答题记录删除失败，请检查浏览器存储权限后重试。');return false}render();showInteractionNotice('答题记录已删除。');return true}
function ask(){return `<section class="page"><div class="eyebrow">OFFLINE KNOWLEDGE CONSOLE</div><h2>通信知识问答</h2><p class="lead">本地规则知识库，无需联网，不会调用在线人工智能。</p><div class="conversation card task-panel"><div id="chat"><div class="bubble">本地知识库已就绪。可查询1G到6G的特点、GSM、LTE、短信、移动互联网、5G工业应用、6G研究或时代差异。</div></div><form onsubmit="askQuestion(event)" class="actions"><input id="askInput" placeholder="例如：5G和4G有什么不同？" style="flex:1;min-width:190px;padding:13px;border-radius:9px;background:#081426;color:white;border:1px solid #6686a866"><button class="btn">发送问题</button></form><div class="tools"><button class="quiet" onclick="quickAsk('6G现在已经商用了吗？')">6G现在已经商用了吗？</button><button class="quiet" onclick="quickAsk('什么是GSM？')">什么是GSM？</button><button class="quiet" onclick="quickAsk('5G有什么特点？')">5G有什么特点？</button></div></div></section>`}
function answerKnowledge(q){
 const x=String(q).normalize('NFKC').toLowerCase();
 const comparisonIntent=/(?:不同|区别|差异|对比|相比|比较|相较|vs\.?|versus)/i.test(x);
 const eraAliases=[['1G',/(?:\b1g\b|第一代|1代)/i],['2G',/(?:\b2g\b|第二代|2代)/i],['3G',/(?:\b3g\b|第三代|3代)/i],['4G',/(?:\b4g\b|第四代|4代)/i],['5G',/(?:\b5g\b|第五代|5代)/i],['6G',/(?:\b6g\b|第六代|6代)/i]];
 const compared=eraAliases.filter(([,pattern])=>pattern.test(x)).map(([id])=>id);
 const singleEra=compared.length===1?compared[0]:null;
 if(comparisonIntent&&compared.length>=2){
  const descriptions={
   '1G':'模拟蜂窝移动通信，以语音通话为主，覆盖和容量有限。',
   '2G':'转向数字蜂窝通信，并普及短信等数字服务。',
   '3G':'提升移动数据承载能力，推动手机互联网和多媒体服务发展。',
   '4G':'以LTE移动宽带为代表，推动高速上网、视频和移动服务普及。',
   '5G':'在移动宽带基础上，扩展低时延和大量设备连接等应用方向。',
   '6G':'仍处研究与标准制定阶段，探索通信感知融合和智能协同，尚非成熟商用网络。'
  };
  return '按你提到的时代对比：'+compared.map(id=>id+'：'+descriptions[id]).join('；');
 }
 if(comparisonIntent&&compared.length===0)return '可以按代际理解：1G以模拟移动语音为主；2G转向数字语音并提供短信；3G提升移动数据能力；4G普及移动宽带与视频服务；5G扩展低时延和设备连接等应用；6G仍处研究与标准制定阶段。';
 if(singleEra==='6G'||(!singleEra&&/6g|第六代/.test(x)))return '6G仍处于研究、标准制定与技术验证阶段。AI、传感器和数字孪生已有应用；IMT-2030中的融合场景与能力目标不能当作商用性能。本项目城市与调查结果均属模拟。';
 if(singleEra==='5G'||(!singleEra&&/5g|第五代|工业/.test(x)))return '5G扩展了移动宽带、低时延和大规模连接等能力，为工业互联网与设备协同提供通信基础。实际工业应用仍依赖传感器、控制系统、安全和可靠性设计。';
 if(singleEra==='4G'||(!singleEra&&/4g|第四代|lte|直播/.test(x)))return '4G/LTE推动高速移动网络与移动宽带应用发展，视频、直播和移动服务更普及。端到端体验还受网络拥塞、终端解码及服务端响应影响。';
 if(singleEra==='3G'||(!singleEra&&/3g|第三代|网页|移动互联网/.test(x)))return '手机上网并非始于3G：GPRS等早期移动数据服务已存在。3G进一步提高数据承载能力，推动网页和多媒体应用；体验仍依赖网络、终端和服务协同。';
 if(singleEra==='2G'||(!singleEra&&/2g|第二代|gsm|短信/.test(x)))return '2G以数字移动通信为代表，GSM是重要的第二代蜂窝移动通信系统之一。短信等服务让信息可异步传递，通信从以语音为主扩展到数字信息。';
 if(singleEra==='1G'||(!singleEra&&/1g|第一代|模拟/.test(x)))return '1G通常指第一代模拟蜂窝移动通信，以移动语音通话为主。它让通话摆脱固定线路，但覆盖范围、容量等仍有限。';
 if(/演进/.test(x))return '可以概括为：1G模拟移动语音；2G数字语音与短信；3G提升移动数据承载能力；4G移动宽带与视频服务普及；5G扩展到更多设备连接和工业应用；6G仍处研究阶段，探索通信、感知与智能系统协同。';
 return '本地知识库暂未匹配。你可以询问1G、2G、3G、4G、5G、6G的特点与差异，或询问GSM、LTE、短信、移动互联网、工业互联网、数字孪生。'
}function quickAsk(q){const input=document.querySelector('#askInput');if(input)input.value=q;askQuestion(new Event('submit',{cancelable:true}))}function askQuestion(ev){ev.preventDefault();const input=document.querySelector('#askInput'),q=input.value.trim();if(!q)return;document.querySelector('#chat').innerHTML+=`<div class="bubble user">${escapeHtml(q)}</div><div class="bubble"><b style="color:var(--cyan)">澜</b><br>${answerKnowledge(q)}</div>`;input.value='';document.querySelector('#chat').scrollIntoView({behavior:'smooth',block:'end'})}function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function finalPage(){const visited=[...new Set((state.visited||[]).filter(id=>eras.some(item=>item.id===id)))],evidenceCount=(state.evidence||[]).length,logCount=(state.logs||[]).length,archiveCount=(window.CommsArchiveLan?.LanMemory?.eraArchives||[]).filter(item=>item.completed).length;return `<section class="page final-page" style="text-align:center;padding-top:8vh"><div class="eyebrow">通信简史：从1G到6G · JOURNEY COMPLETE</div><h1>连接，仍在继续。</h1><p class="lead">这次旅程回顾了1G—5G的发展历史，并走进6G的未来研究展望。你参与的是项目设计的模拟调查；6G仍处研究、标准制定与技术验证阶段，尚不能视为人类已经经历的成熟商用时代。关于连接与探索的故事还在继续。</p><div class="final-achievement-grid" aria-label="本次探索成果"><article><strong>${visited.length}</strong><span>到访时代</span><small>${visited.length?visited.map(escapeHtml).join(' · '):'尚无时代记录'}</small></article><article><strong>${evidenceCount}</strong><span>调查证据</span><small>已写入个人档案</small></article><article><strong>${logCount}</strong><span>时空日志</span><small>${archiveCount} 份年代总结</small></article></div><div class="archive-record" style="max-width:720px;margin:30px auto;text-align:left"><h3>从连接人与人，到连接万物，再到探索数字世界的未来。</h3><p>感谢参与通信简史的穿越之旅。</p></div><div class="actions" style="justify-content:center"><button class="btn" onclick="resetAndStart()">重新开始穿越</button><button class="btn secondary" onclick="go(\'archive\')">查看全部文明档案</button><button class="btn ghost" onclick="go('home')">返回通信简史</button></div></section>`}
function resetAndStart(){if(!confirm('重新开始会清除本机的探索进度，是否继续？'))return false;return resetFormalExploration()}
function modal(content){const root=document.querySelector('#modalRoot');if(!root.innerHTML)modalTrigger=document.activeElement;const previousModal=root.querySelector('.modal'),savedScrollTop=previousModal?.scrollTop||0;root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div>${content}</div><button class="close" onclick="closeModal()">关闭 ×</button></div></div></div>`;if(previousModal)requestAnimationFrame(()=>{const currentModal=root.querySelector('.modal');if(currentModal)currentModal.scrollTop=savedScrollTop})}function closeModal(){const returningToCatalogue=currentExhibitSource==='guided-catalogue'&&currentExhibitId&&route==='chapter';if(returningToCatalogue){const view=exhibitCatalogueViewState[exhibitCatalogueStateKey(currentExhibitId)];if(view?.expanded)pendingRouteScrollRestore=view.scrollY}pauseFlow();document.querySelector('#modalRoot').innerHTML='';currentExhibitId=null;const trigger=modalTrigger;modalTrigger=null;trigger?.focus?.({preventScroll:true});if(route==='chapter')render()}
