function complete6GExperience(nodeId){return completeEraExperienceNode('6G',nodeId)}
function preservePagePosition(targetY){const root=document.documentElement;if(scrollRestoreStyle===null)scrollRestoreStyle={value:root.style.getPropertyValue('scroll-behavior'),priority:root.style.getPropertyPriority('scroll-behavior')};const token=++scrollRestoreToken;root.style.setProperty('scroll-behavior','auto','important');window.scrollTo(0,targetY);requestAnimationFrame(()=>{if(token!==scrollRestoreToken)return;window.scrollTo(0,targetY);requestAnimationFrame(()=>{if(token!==scrollRestoreToken)return;if(scrollRestoreStyle.value)root.style.setProperty('scroll-behavior',scrollRestoreStyle.value,scrollRestoreStyle.priority);else root.style.removeProperty('scroll-behavior');scrollRestoreStyle=null})})}function syncEraVisualMode(){const era=(route==='chapter'||route==='chapter-end')?eras[eraIndex]?.id||'':'';const finalEra=route==='final'&&(state.completed||[]).includes('6G')?'6G':'';if(document.body?.dataset)document.body.dataset.currentEra=era||finalEra||''}function render(){const renderKey=route+((route==='chapter'||route==='chapter-end')?':'+(eras[eraIndex]?.id||''):'');const previousScroll=window.scrollY||0,keepScroll=renderKey===lastRenderedRouteKey,explicitScrollRestore=pendingRouteScrollRestore;pendingRouteScrollRestore=null;syncEraVisualMode();updateProgress();let content=route==='home'?home():route==='prologue'?prologue():route==='transit'?transitPage():route==='eras'?erasPage():route==='chapter'?chapter():route==='chapter-end'?endPage():route==='archive'?archive():route==='search'?window.CommsArchiveKnowledgeSearch.renderPage():route==='quiz'?quiz():route==='ask'?ask():finalPage();if(reviewGuideActive&&(route==='chapter'||route==='chapter-end'||route==='archive')){const msg=route==='chapter'?'依次查看历史展品、完成建设调查，再到技术实验室理解原理；使用页面底部按钮前往下一环节。':route==='chapter-end'?'调查已归档；打开档案馆查看技术资料证据与调查结果卡。':'评审路线完成。证据卡、关联展品和历史来源都在此档案馆中。';content='<div class="review-inline"><span class="eyebrow">首次调查路线 · 可随时关闭</span><span>'+msg+'</span><button class="quiet" onclick="go(\'archive\')">查看档案馆 →</button><button class="quiet" onclick="dismissReviewGuide()">关闭引导 ×</button></div>'+content}app.innerHTML=content;const suppressAutoDialogue=suppressLanAutoDialogueOnce;suppressLanAutoDialogueOnce=false;window.CommsArchiveLan?.onRoute(route,{era:eras[eraIndex]?.id,completed:state.completed,suppressAutoDialogue});window.CommsArchiveLan?.checkGuidedDialogueState?.({route,era:eras[eraIndex]?.id});window.DemoManager?.saveView(route,eraIndex);window.DemoGuide?.refresh();if(route==='quiz')quizRender();lastRenderedRouteKey=renderKey;preservePagePosition(explicitScrollRestore??(keepScroll?previousScroll:0))}window.renderProgression=render;document.addEventListener('click',e=>{const b=e.target.closest('[data-nav]');if(b){e.preventDefault();go(b.dataset.nav)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('#imageViewerRoot').innerHTML)closeImageViewer();else if(document.querySelector('#modalRoot').innerHTML)closeModal()}});window.CommsArchiveApp={status:'initializing',reason:null,getRoute(){return route},getHomeProgressStatus(){const status=homeFormalProgressStatus();return{hasProgress:status.hasProgress,reasons:[...status.reasons],mode:window.DemoManager?.isActive?.()?'demo':'normal',formalSaveKey:'commsArchive'}},getInteractionState(){return{route,era:eras[eraIndex]?.id||null,transitionInProgress,galleryActive,modalOpen:!!document.querySelector('#modalRoot')?.innerHTML,dialogue:window.CommsArchiveLan?.debugSnapshot?.()||null,demoMode:!!window.DemoManager?.isActive?.()}},getEraStatus(){return eras.map((era,index)=>{const access=progressionEraAllowed(era.id);return{id:era.id,index,status:state.completed.includes(era.id)?'completed':state.visited.includes(era.id)?'visited':access.ok?'available':'locked',access:access.ok,reason:access.reason||''}})}};try{render();window.CommsArchiveApp.status='ready';window.CommsArchiveApp.reason=null;const eraStatus=window.CommsArchiveApp.getEraStatus();window.InteractionDebugger?.record('ERA_STATUS','app.init',{eras:eraStatus});if(window.InteractionDebugger?.enabled)console.table?.(eraStatus);window.dispatchEvent(new Event('comms-archive-app-ready'))}catch(error){window.CommsArchiveApp.status='failed';window.CommsArchiveApp.reason=error?.message||String(error);console.error('APP_INIT_FAILED',error);window.dispatchEvent(new Event('comms-archive-app-failed'));throw error}
